import {createUniversityCampaign,matchesUniversityMessage,universityVisitToken} from './university-campaign.mjs?v=p21-b407-s039-reuse';
import {createCase01} from "./university-case/candidate-connector.mjs?v=cw1";
import {mountCase01Panel} from "./university-case/host-panel.mjs?v=cw2";
export function createUniversityHost({city,makeStore,document:doc=document,host=window}){
 const ledger=createUniversityCampaign({makeStore,world:city.world,position:city.position,visits:city.visits,steps:city.steps,stop:city.stop,restore:p=>{city.restore(p);city.update();}});
 const link=doc.createElement('link');link.rel='stylesheet';link.href=new URL('university-host.css?v=p21-b502-university-ui',import.meta.url);doc.head.append(link);
 const dialog=doc.createElement('dialog');dialog.id='cw-university-host';dialog.className='cw-interior-opening';dialog.setAttribute('aria-labelledby','cw-university-host-title');dialog.innerHTML='<header><h2 class="cw-opening-title" id="cw-university-host-title">Unseen University</h2><button type="button" id="cw-university-leave">Return to city</button></header><div class="cw-university-recovery cw-opening-panel"><p id="cw-university-status" role="status">Opening the University…</p><button type="button" id="cw-university-retry" hidden>Retry</button></div><iframe title="Unseen University interior" id="cw-university-frame"></iframe>';doc.body.append(dialog);
 const frame=dialog.querySelector('iframe'),status=dialog.querySelector('[role="status"]'),leave=dialog.querySelector('#cw-university-leave'),retry=dialog.querySelector('#cw-university-retry');let visit=null,session=null,loaded=false,returning=false,pending=null,restoreNeeded=false,focus=null,timer=null,lastSequence=0,lastCheckpoint=null,walkingTo=null;
 const caseStyle=link.cloneNode();caseStyle.href=new URL('university-case/host-panel.css',import.meta.url);doc.head.append(caseStyle);
 const isSettled=()=>loaded&&!returning&&!pending;
 const inquiryCase=createCase01({makeStore,university:ledger,isSettled});
 const artState=()=>{try{const s=inquiryCase.view().case;return {recovered:s.recovered};}catch{return {recovered:false};}};
 const inquiry=mountCase01Panel({doc,header:dialog.querySelector('header'),case01:inquiryCase,university:ledger,isSettled,onChange:cue=>send('case-art',{art:{...artState(),...cue}}),walkTo:position=>{if(!isSettled()||!visit)return false;walkingTo=JSON.stringify(position);send('walk-to',{position});return true;}});
 const send=(type,extra={})=>{if(visit&&session)frame.contentWindow?.postMessage({protocol:'cw-university-1',session,type,...extra},host.location.origin);};
 function clear(){inquiry.show(false);walkingTo=null;clearTimeout(timer);session=null;loaded=false;returning=false;pending=null;visit=null;frame.src='about:blank';if(dialog.open)dialog.close();focus?.isConnected&&focus.focus({preventScroll:true});city.update();}
 function cancel(){if(!visit)return;try{ledger.cancel(visit.id);clear();city.tell('Returned to the same University entrance. Your saved room progress is retained.');}catch(e){status.textContent=e.message;}}
 function open(active){inquiry.show(false);if(!dialog.open)focus=doc.activeElement;visit=active;loaded=false;returning=false;pending=null;restoreNeeded=false;session=universityVisitToken();retry.hidden=true;retry.textContent='Retry';leave.disabled=false;leave.textContent='Cancel';frame.inert=true;dialog.dataset.loading='';status.hidden=false;status.textContent='Opening the University…';frame.src=new URL('modules/university/index.html?v=source-hd-1&campaign=1&session='+encodeURIComponent(session),import.meta.url).href;if(!dialog.open)dialog.showModal();clearTimeout(timer);timer=host.setTimeout(()=>{if(!loaded&&visit){status.textContent='The University is taking longer to load. Retry, or return to the city.';retry.hidden=false;}},25000);}
 async function enter(){if(visit)return false;try{open(ledger.enter());return true;}catch(e){city.tell(e.message);return false;}}
 function resume(){try{const a=ledger.active();if(!a)return false;city.stop();open(a);return true;}catch(e){city.tell(e.message);return false;}}
 function saved(packet){try{if(packet.sequence<lastSequence)return false;if(packet.sequence===lastSequence){if(JSON.stringify(packet.snapshot)!==lastCheckpoint)throw Error('A saved checkpoint cannot be replaced by a different position');send('saved',{sequence:packet.sequence,snapshot:ledger.active().snapshot});return true;}const snapshot=ledger.save(visit.id,packet.snapshot);lastSequence=packet.sequence;lastCheckpoint=JSON.stringify(packet.snapshot);pending=null;retry.hidden=true;send('saved',{sequence:packet.sequence,snapshot});if(walkingTo&&!returning&&JSON.stringify(snapshot?.position)===walkingTo){walkingTo=null;host.setTimeout(()=>inquiry.reopen(),300);}status.textContent=returning?'Returning through the University to the Great Gates…':'University progress saved.';status.hidden=!returning;return true;}catch(e){pending=packet;restoreNeeded=e.code==='UU_INVALID_TRANSITION';retry.hidden=false;retry.textContent=restoreNeeded?'Restore last save':'Retry';status.hidden=false;status.textContent=restoreNeeded?'That step did not follow an open doorway or stair. Restore your last saved position to continue.':'Progress could not be saved. Retry before continuing. '+e.message;send('save-failed',{sequence:packet.sequence,message:restoreNeeded?'Use Restore last save above the map.':'Progress could not be saved. Use Save to retry.'});return false;}}
 host.addEventListener('message',event=>{if(!visit||!matchesUniversityMessage(event,{origin:host.location.origin,source:frame.contentWindow,session}))return;const packet=event.data;switch(packet.type){case'ready':try{const current=ledger.active();if(!current||current.id!==visit.id)throw Error('This University visit is no longer active');visit=current;pending=null;lastSequence=0;lastCheckpoint=null;retry.hidden=true;send('init',{snapshot:current.snapshot,art:artState(),returning});}catch(e){loaded=false;status.hidden=false;status.textContent=e.message;retry.hidden=false;}break;case'presented':if(!loaded){clearTimeout(timer);loaded=true;retry.hidden=true;status.hidden=true;leave.textContent='Return to city';frame.inert=false;delete dialog.dataset.loading;inquiry.show(true);frame.focus({preventScroll:true});}break;case'checkpoint':if(loaded&&Number.isSafeInteger(packet.sequence)&&packet.sequence>0)saved(packet);break;case'leave':try{if(pending)throw Error('Retry saving before leaving');if(ledger.finish(visit.id,packet.snapshot)){clear();city.tell('Returned to the same University entrance.');}}catch(e){status.hidden=false;status.textContent=e.message;}break;case'cancel-return':returning=false;leave.textContent='Return to city';status.hidden=true;break;case'load-error':clearTimeout(timer);status.hidden=false;status.textContent='The University could not load. Retry, or return to the city.';retry.hidden=false;loaded=false;inquiry.show(false);break;}});
 leave.onclick=()=>{if(!loaded){cancel();return;}if(pending){status.hidden=false;status.textContent=restoreNeeded?'Restore your last saved position before leaving the University.':'Retry saving before leaving the University.';return;}returning=!returning;leave.textContent=returning?'Cancel return':'Return to city';status.hidden=!returning;status.textContent='Returning through the University to the Great Gates…';send(returning?'return':'cancel-return');};
 retry.onclick=()=>{if(restoreNeeded&&visit){try{const savedVisit=ledger.active();if(!savedVisit||savedVisit.id!==visit.id)throw Error('This University visit is no longer active');open(savedVisit);}catch(e){status.textContent=e.message;}}else if(pending)saved(pending);else if(visit)open(ledger.active());};dialog.addEventListener('cancel',e=>{e.preventDefault();leave.click();});
 return Object.freeze({enter,resume,dialog,ledger,frame});
}
